export const theory = {
  waermeuebertragung: {
    updated:'19. November 2026',
    intro:'Warum kühlt eine offene Tasse ab? Verfolge zunächst die gespeicherte Wärmeenergie, dann die Mischung und schließlich den Wärmeaustausch mit der Umgebung. An zwei Tassen lässt sich untersuchen, wann allein der Zugabezeitpunkt einen Unterschied macht.',
    sources:[
      {id:'cooling',title:'Memorial University · Coffee Cooling',url:'https://www.engr.mun.ca/~ggeorge/CoffeeCooling.pdf',role:'Analytische Herleitung des Zugabevergleichs unter idealisierten Annahmen.'},
      {id:'ferreira',title:'J. P. M. Ferreira · How a soup bowl and a coffee cup cool down',url:'https://doi.org/10.1088/1361-6552/ad6ac9',role:'Experimentelle Einordnung von Verdunstung, Konvektion und Strahlung bei offenen Gefäßen.'}
    ],
    chapters:[
      {id:'kapazitaet',title:'1 · Wie viel Wärme speichert eine Tasse?',paragraphs:['Für dieselbe Temperaturänderung braucht eine größere Flüssigkeitsmenge mehr Energie. Auch die Gefäßwand kann einen Teil der beim Eingießen abgegebenen Wärme aufnehmen.','Die Wärmekapazität C beschreibt die Energie pro Temperaturänderung. Sie hängt von der Masse und der spezifischen Wärmekapazität des Stoffes ab.'],equation:'C = m cₚ · Q = C ΔT',detail:'Masse in kg, cₚ in J/(kg K), C in J/K und Energie Q in J. Eine Temperaturdifferenz hat in °C und K denselben Zahlenwert.',tools:['kaffee-und-milch'],sources:['cooling','ferreira']},
      {id:'mischung',title:'2 · Was passiert beim Eingießen?',paragraphs:['Wärmere Bestandteile geben Energie ab, kühlere nehmen sie auf. Bei vollständiger Mischung stellt sich eine gemeinsame Temperatur ein.','Bei unterschiedlich großen Portionen liegt die Mischtemperatur näher an der Temperatur des Bestandteils mit der größeren Wärmekapazität.'],equation:'Tₘ = (C₁T₁ + C₂T₂)/(C₁ + C₂)',detail:'Für den augenblicklichen Mischschritt wird der Wärmeaustausch mit der Umgebung vernachlässigt. Eine bereits angeglichene Gefäßwand zählt zur ersten Wärmekapazität.',tools:['kaffee-und-milch'],sources:['cooling']},
      {id:'abkuehlung',title:'3 · Warum flacht die Temperaturkurve ab?',paragraphs:['In warmer Flüssigkeit steht ein Temperaturunterschied zur Raumluft als Antrieb für Wärmeübertragung zur Verfügung. Wird der Unterschied kleiner, sinkt im linearen Modell der Wärmestrom.','Ein Deckel verringert Verluste über die Öffnung. Verdunstung kann bei offenen Gefäßen wesentlich zur Kühlung beitragen.'],equation:'C dT/dt = −G (T − Tᵤ) · τ = C/G',detail:'G ist ein effektiver Wärmeleitwert in W/K. Die Zeitkonstante τ in Sekunden beschreibt den Rückgang der Temperaturdifferenz auf etwa 37 Prozent. Reale Leitwerte können mit Temperatur und Füllstand variieren.',tools:['kaffee-und-milch'],sources:['ferreira','cooling']},
      {id:'zeitvergleich',title:'4 · Wann zählt die Reihenfolge?',paragraphs:['Vergleiche die Temperaturen zu derselben Uhrzeit und beachte, ob schon beide Zugaben erfolgt sind. Die spätere Zugabe kann die Reihenfolge der Temperaturen schlagartig ändern.','Ein ideal isoliertes System mit konstant temperierter Zugabe liefert nach dem Mischen für beide Zeitpunkte dasselbe Ergebnis. Erwärmt sich die wartende Portion im Raum, ändert sich diese Ausgangslage.'],equation:'ΔT(t) = Tₐ(t) − Tᵦ(t)',detail:'Eine unabhängige Messung benötigt vergleichbare Gefäße, Füllmengen, Starttemperaturen und Mischbedingungen. Die Gefäßprofile im Werkzeug sind frei gewählte Lehrannahmen.',tools:['kaffee-und-milch'],sources:['cooling','ferreira']}
    ]
  },
  elektrochemie: {
    updated:'21. November 2026',
    intro: 'Elektrochemie verbindet chemische Reaktionen mit elektrischer Ladung. Dieser Lernweg führt vom Elektrodenpotential über Strom und Stofftransport zu Messkurven und zur Elektrokristallisation. Die allgemeinen Beziehungen erklären die Werkzeuge; ihre vereinfachten Modellparameter müssen für ein reales System gesondert geprüft werden.',
    sources: [
      {id:'werkstoff-korrosion',title:'Bargel & Siemer (Hrsg.) · Werkstoffkunde, 14. Auflage (2026)',url:'https://doi.org/10.1007/978-3-662-71672-4',role:'Kapitel 1.8, S. 70–83: Korrosionsvorgänge, Passivität und Korrosionsschutz. Hintergrund für die Lehrfälle; keine Quelle der EIS-Topologien oder Zahlenwerte.'},
      {id:'corrosion', title:'Gamry · Electrochemical corrosion measurements', url:'https://www.gamry.com/application-notes/corrosion-coatings/basics-of-electrochemical-corrosion-measurements/', role:'Herstellerunterlage zu Teilreaktionen, Tafel-Näherung und Transportgrenzen.'},
      {id:'faraday', title:'Gamry · Equivalent Weight Calculator', url:'https://www.gamry.com/resources-2/electrochemical-calculators-tools/equivalent-weight-calculator', role:'Zuordnung von Molmasse und Elektronenzahl zur umgesetzten Metallmasse.'},
      {id:'nernst', title:'IUPAC Gold Book · Nernst equation', url:'https://goldbook.iupac.org/terms/view/09068/plain', role:'Definition des Gleichgewichtspotentials und der Nernst-Beziehung.'},
      {id:'eta', title:'IUPAC Gold Book · Overpotential', url:'https://goldbook.iupac.org/terms/view/O04358/pdf', role:'Begriffsdefinition der Überspannung als Abweichung vom Gleichgewichtspotential.'},
      {id:'eis', title:'IUPAC · Impedances of electrochemical systems', url:'https://media.iupac.org/publications/pac/1994/pdf/6609x1831.pdf', role:'Terminologie und Darstellung komplexer Impedanzen, einschließlich Stofftransportanteilen.'},
      {id:'eis-models', title:'Gamry · Basics of Electrochemical Impedance Spectroscopy', url:'https://www.gamry.com/application-notes/EIS/basics-of-electrochemical-impedance-spectroscopy/', role:'Randles-, Beschichtungs- und Diffusionsmodelle; Herstellerunterlage mit idealisierten Anwendungsbeispielen.'},
      {id:'eis-battery', title:'MathWorks · Battery Equivalent Circuit', url:'https://www.mathworks.com/help/simscape-battery/ref/batteryequivalentcircuit.html', role:'RC-Zweige für Batteriedynamik. Das EIS-Tool übernimmt nur die Kleinsignalimpedanz, kein vollständiges Batterie-Zustandsmodell.'},
      {id:'winand', title:'R. Winand · Electrocrystallization – theory and applications', url:'https://doi.org/10.1016/0304-386X(92)90033-V', role:'Fachliche Grundlage für den qualitativen Zusammenhang von Hemmung, Stofftransport und Abscheidungstypen.'}
    ],
    chapters: [
      {id:'korrosionsauswertung', title:'Potentialkurven prüfen und mittleren Abtrag berechnen', paragraphs:[
        'Eine Tafel-Auswertung benötigt aktivierungskontrollierte Bereiche. Neben R² ist die Empfindlichkeit gegenüber Fensterlage und Breite zu prüfen. Das Tool verschiebt jedes Fenster um −10, 0 und +10 mV und skaliert die Breite mit 0,8, 1 und 1,2. Die Spannweiten geeigneter Varianten beschreiben Auswahlabhängigkeit und sind keine Konfidenzintervalle.',
        'Plateaus und Krümmung können auf Transport, Passivität oder weitere Einflüsse hinweisen. Die Bereichsprüfung meldet höchstens 0,15 Dekaden Stromspanne als Plateau und mehr als 30 % Unterschied der Halbfenster-Steigungen als Krümmung. Diese heuristischen Schwellen beweisen keinen Mechanismus. Das zuschaltbare Teilstrommodell beschreibt zwei aktivierungskontrollierte Reaktionen ohne Transport und Passivierung.',
        'Die Faraday-Umrechnung benötigt eine zugeordnete Auflösungsreaktion, Molmasse, Elektronenzahl, Dichte und Auflösungsanteil. Jahresraten setzen konstante Bedingungen und flächige Auflösung voraus. Lokale Lochfraßtiefen sind daraus nicht bestimmbar.'
      ], equation:'m = j A t M η/(n F);   h = j t M η/(n F ρ)', detail:'Mit j in A/cm², A in cm², t in s, M in g/mol und ρ in g/cm³ folgen m in g und h in cm. F = 96485,33212 C/mol. η ist der Anteil des zugeordneten Auflösungsstroms. Für Legierungen eine geeignete Reaktionszuordnung verwenden.', tools:['potentialkurven'], sources:['corrosion','faraday']},
      {id:'potential', title:'1 · Potential, Gleichgewicht und Referenzelektrode', paragraphs:[
        'Bei einer Elektrodenreaktion wechseln Elektronen zwischen einem elektronischen Leiter und redoxaktiven Spezies. Ein Elektrodenpotential ist eine Potentialdifferenz relativ zu einer Referenz. Deshalb gehören Referenzelektrode, Temperatur und Lösung zur Angabe eines Messwerts. Zahlen mit unterschiedlichem Bezug lassen sich erst nach einer passenden Umrechnung vergleichen.',
        'Für eine als Reduktion geschriebene Reaktion verknüpft die Nernst-Gleichung das Gleichgewichtspotential mit den Aktivitäten der beteiligten Spezies. Aktivität ist eine thermodynamisch wirksame Größe. Das Ersetzen durch Konzentrationen ist eine zusätzliche Näherung, besonders in konzentrierten oder stark komplexierenden Elektrolyten.',
        'Das gemessene Ruhepotential muss kein Gleichgewicht einer einzigen Reaktion sein. An korrodierenden Oberflächen können sich anodische und kathodische Teilströme bei einem Mischpotential aufheben. Ein äußerlich stromloser Zustand schließt deshalb einen chemischen Umsatz nicht aus.'
      ], equation:'Eeq = E° − (RT / nF) ln Q', detail:'Eeq und E° werden in Volt angegeben. R ist die Gaskonstante, T die absolute Temperatur in Kelvin, F die Faraday-Konstante, n die übertragene Elektronenzahl und Q der dimensionslose Reaktionsquotient. Zuerst die Reaktionsrichtung und den Bezug prüfen; sonst werden Vorzeichen leicht verwechselt.', tools:['potentialkurven'], sources:['nernst']},
      {id:'kinetik', title:'2 · Überspannung, Ladungstransfer und Polarisation', paragraphs:[
        'Ein endlicher Reaktionsstrom benötigt im Allgemeinen eine Abweichung vom Gleichgewicht. Diese Überspannung beeinflusst die Geschwindigkeiten der anodischen und kathodischen Teilreaktionen. Zusätzlich kann zwischen Messgerät und Grenzfläche ein ohmscher Spannungsabfall auftreten. Gemessene Potentialänderung und reine Ladungstransfer-Überspannung sind daher sorgfältig zu unterscheiden.',
        'Nahe einem geeigneten Arbeitspunkt lässt sich eine Strom-Potential-Kurve lokal linearisieren. Der inverse Anstieg dE/di wird als Polarisationswiderstand betrachtet. Bei Verwendung der Stromdichte ergeben sich andere Einheiten als beim Gesamtstrom. Eine unpassende Flächen- oder Stromeinheit verändert deshalb das Ergebnis direkt.',
        'Tafelgeraden sind eine Näherung in Bereichen, in denen ein Reaktionszweig dominiert. Ein nahezu gerader Verlauf in einer logarithmischen Darstellung genügt allein nicht: Stofftransportbegrenzung, Passivierung, ohmsche Verluste und überlagerte Reaktionen können die Auswertung verfälschen.'
      ], equation:'η = E − Eeq;   Rp = (dE/di) am Arbeitspunkt', detail:'η hat die Einheit V. Bei i in A hat Rp die Einheit Ω, bei Stromdichte j in A/m² hat dE/dj die Einheit Ω·m². Fitfenster, Stromvorzeichen, Fläche und Oberflächenzustand dokumentieren. Ein hoher Korrelationskoeffizient ist kein Nachweis des Reaktionsmechanismus.', tools:['potentialkurven'], sources:['eta']},
      {id:'impedanz', title:'3 · Impedanz, Frequenz und Zeitkonstanten', paragraphs:[
        'Die Impedanz beschreibt bei sinusförmiger kleiner Anregung das Verhältnis zwischen Spannungs- und Stromantwort einschließlich Phasenverschiebung. Durch Variation der Frequenz lassen sich Prozesse mit unterschiedlichen charakteristischen Zeiten untersuchen. Für die übliche Interpretation werden näherungsweise lineares Verhalten und ein ausreichend stationärer Zustand benötigt.',
        'Im Nyquist-Diagramm werden Real- und Imaginärteil gegeneinander dargestellt. Bei der häufigen Achsenwahl −Im(Z) über Re(Z) liegen kapazitive Bögen oberhalb der reellen Achse. Die Frequenz ist dabei keine eigene Koordinate. Die Bode-Darstellung zeigt Betrag und Phase über der Frequenz und erleichtert die Zuordnung schneller und langsamer Anteile.',
        'Ein paralleler Widerstand mit einem idealen Kondensator besitzt eine charakteristische Zeit τ = RC. Der Ort eines Bogens oder einer Phasenänderung kann auf eine Zeitkonstante hinweisen. Er beweist für sich genommen weder eine bestimmte Grenzfläche noch einen einzigen elementaren Prozess.'
      ], equation:'Z(ω) = Ũ(ω) / Ĩ(ω);   ω = 2πf;   τ = RC', detail:'Z in Ω, Frequenz f in Hz, Winkelgeschwindigkeit ω in rad/s, R in Ω und C in F ergeben τ in s. Reale Systeme können verteilte Zeitkonstanten, Diffusion und zeitliche Drift aufweisen. Die Anregungsamplitude so wählen, dass die Linearitätsannahme geprüft werden kann.', tools:['eis-fitting'], sources:['eis']},
      {id:'korrosionsmodelle', title:'Schutzschichten und Grenzflächen · fünf EIS-Lehrfälle', paragraphs:[
        'Elektrochemische Korrosion koppelt anodische Metalloxidation an eine kathodische Reaktion, beispielsweise Sauerstoffreduktion oder Wasserstoffentwicklung. Elektronenleitung im Metall und Ionenleitung im Elektrolyten schließen den Stromkreis. Auch bei äußerlich stromlosem Zustand können Teilströme und Metallauflösung bestehen. Passivierende Oberflächenfilme und aufgebrachte Beschichtungen können die Reaktion beziehungsweise den Zutritt von Elektrolyt und Reaktionspartnern hemmen.',
        'Im EIS-Tool veranschaulichen fünf interaktive, ausdrücklich synthetische Lehrfälle mögliche Modellannahmen: Metall/Elektrolyt mit Rₛ + (Rct ∥ Cdl); ideal sperrende Beschichtung mit Rₛ + Ccoat; endlicher Schichtwiderstand mit Rₛ + (Rcoat ∥ Ccoat); durchlässige Beschichtung mit Rₛ + [Ccoat ∥ (Rpore + (Rct ∥ Cdl))]; Oberflächenfilm und Grenzfläche mit Rₛ + (Rfilm ∥ Cfilm) + (Rct ∥ Cdl). Der letzte Fall ist ein phänomenologisches Modell zweier Zeitkonstanten, keine universelle Passivschichtschaltung.',
        'Die Lehrwerte sind frei gewählt und veränderbar. Bode- und Nyquist-Kurven entstehen direkt aus den komplexen Bauteilimpedanzen. Zwei getrennte RC-Zeitkonstanten können zwei Bögen ergeben; bei Überlappung verschwinden erkennbare Einzelbögen. Dieselbe RC-Topologie kann unterschiedliche physikalische Zuordnungen besitzen. Ein Bogen bestätigt daher weder Poren noch Passivität oder eine bestimmte Reaktion.'
      ],equation:'ZReihe = Σ Zₖ;   Zparallel = (Σ 1/Zₖ)⁻¹;   τ = RC;   Ccoat ≈ ε₀ εᵣ A/d',detail:'R in Ω, C in F, τ in s; Kapazitätsnäherung für eine homogene Schicht mit Fläche A in m² und Dicke d in m. Keine Flächennormierung der Lehrwerte. Aus Kapazität allein folgen weder Schichtdicke noch Wasseraufnahme eindeutig. Ladungstransferwiderstand und gesamter Polarisationswiderstand sind nicht allgemein gleich; eine Korrosionsrate erfordert zusätzliche kinetische und experimentelle Voraussetzungen. Das Lehrbuch begründet den Werkstoffkontext; EIS-Quellen begründen idealisierte Schaltungen. Messdaten bleiben beim Erkunden unverändert.',tools:['eis-fitting'],sources:['werkstoff-korrosion','eis-models','eis']},
      {id:'fit', title:'4 · Ersatzschaltbilder und belastbare Modellwahl', paragraphs:[
        'Ein Ersatzschaltbild ist ein mathematisches Modell der beobachteten Antwort. Widerstände, Kapazitäten und Diffusionselemente fassen das Verhalten zusammen. Eine gute Anpassung macht die Bauteilwerte noch nicht automatisch zu eindeutig bestimmten Materialkennwerten. Mehrere Schaltungen können in einem begrenzten Frequenzbereich ähnlich gut passen.',
        'Für die Modellwahl zählen neben dem Fehler auch physikalische Plausibilität, Zahl der freien Parameter, Datenqualität und die abgedeckte Frequenzspanne. Residuen sollten betrachtet werden: Systematische Abweichungen enthalten oft mehr Information als eine einzelne zusammengefasste Fehlerzahl.',
        'Eine Frequenzprognose wertet das gefittete Modell außerhalb der Messung aus. Dort fehlen Messpunkte zur Kontrolle. Neue Prozesse oder schlecht bestimmte Parameter können den extrapolierten Verlauf stark verändern. Die Prognose muss daher erkennbar vom gemessenen Bereich getrennt bleiben.'
      ], equation:'Messung → Modellannahme → Fit → Residuen und Parameter prüfen → unabhängige Plausibilisierung', detail:'Vor einer Interpretation nach Drift, Ausreißern, Kontaktproblemen und fehlenden Frequenzbereichen suchen. Einzelne Messpunkte lassen sich im EIS-Tool manuell ausschließen und wieder einschließen; Originalpunkte bleiben als graue Kreuze sichtbar. Ausschlüsse fachlich begründen und dokumentieren. Ein kleinerer RMS allein rechtfertigt keinen Ausschluss: systematische Abweichungen können auf ein ungeeignetes Modell hinweisen. Alle Modellkandidaten mit derselben Punktauswahl vergleichen; AICc-Werte verschiedener Datensätze nicht unmittelbar vergleichen. Die im Werkzeug angezeigte Fehlerdefinition und Gewichtung beachten. Eine gegliederte Schaltbildbibliothek bietet elektrische RC/RL/RLC-, Randles-, Batterie- und Beschichtungsmodelle als bearbeitbare Ausgangspunkte. Eigene Topologien lassen sich lokal als JSON speichern und für weitere Messungen laden; die Parameter werden dabei jeweils neu gefittet. Eine feste Topologie ersetzt die automatische Modellsuche, aber keine Plausibilitätsprüfung. Glatte Modelllinien werden mit unveränderten Kennwerten auf einem feineren Frequenzraster berechnet; dadurch ändern sich weder Messdaten noch Fehlerkennzahlen. Modellvergleich und Prognose sind bedingt durch diese Annahmen.', tools:['eis-fitting'], sources:['eis','eis-models','eis-battery']},
      {id:'abscheidung', title:'5 · Metallabscheidung, Stofftransport und Morphologie', paragraphs:[
        'Bei der Metallabscheidung wird ein Teil des Stroms für die Reduktion von Metallionen genutzt. Die umgesetzte Stoffmenge hängt von der übertragenen Ladung ab. Nebenreaktionen wie Wasserstoffentwicklung vermindern die Metallstromausbeute. Eine aus Gesamtstrom berechnete Schichtdicke setzt deshalb eine bekannte oder begründet angenommene Stromausbeute voraus.',
        'Auch bei schneller Elektronenübertragung müssen Metallionen die Oberfläche erreichen. Wird ihre Zufuhr zum begrenzenden Faktor, nimmt die Transportbeanspruchung zu. Strömung, Badzusammensetzung, Geometrie und Oberflächenbelegung beeinflussen diese Situation gemeinsam.',
        'Die Winand-Karte ordnet Abscheidungsformen qualitativ nach relativer Strombelastung und Hemmung ein. Sie ist eine Orientierung für Zusammenhänge, keine universell kalibrierte Vorhersage realer Körner. Die genaue Morphologie verlangt elektrolytspezifische Versuche und Charakterisierung.'
      ], equation:'m = ε M Q / (nF);   Q = ∫ I(t) dt', detail:'m ist Masse in kg, M die molare Masse in kg/mol, Q Ladung in C und ε die Metallstromausbeute zwischen 0 und 1. Für Schichtdicke werden zusätzlich Dichte und aktive Fläche benötigt. Zeitabhängige Stromvorgaben müssen über die Zeit integriert werden.', tools:['winand-diagramm'], sources:['winand']}
    ]
  },
  stofftransport: {
    intro:'Stofftransport beschreibt, wie Teilchen oder Flüssigkeit räumlich verlagert werden. Diffusion, Strömung und kapillares Eindringen können gemeinsam wirken. Dieser Lernweg trennt die Mechanismen und erklärt anschließend Randbedingungen, Zeitskalen und die Grenzen numerischer Modelle.',
    sources:[
      {id:'mit',title:'MIT OpenCourseWare · Diffusion',url:'https://ocw.mit.edu/courses/3-091sc-introduction-to-solid-state-chemistry-fall-2010/pages/reactions-and-kinetics/24-diffusion/',role:'Universitärer Einstieg in Fluss, Diffusionskoeffizient und Fick’sche Gesetze.'},
      {id:'comsol',title:'COMSOL · Diffusion Equation',url:'https://www.comsol.com/multiphysics/diffusion-equation',role:'Technische Darstellung der Diffusionsgleichung und ihrer Modellannahmen.'},
      {id:'timescale',title:'COMSOL · Diffusion Length and Timescales',url:'https://www.comsol.com/multiphysics/diffusion-length-and-time-scales',role:'Vertiefung zum Zusammenhang von Diffusionslänge, Diffusionskoeffizient und Zeit.'},
      {id:'model',title:'Keks und Tee · Modell und Implementierung',url:'https://github.com/Werkzeugdeck/keks-und-tee',role:'Offene Implementierung und Tests der illustrativen Sättigungs- und Bruchrechnung. Keine unabhängige experimentelle Validierung.'},
      {id:'fisher',title:'Len Fisher · The art and science of dunking',url:'https://www.lenfisherscience.com/92-the-art-and-science-of-dunking/',role:'Anschaulicher Bezug zwischen porösem Gebäck und kapillarer Flüssigkeitsaufnahme. Keine Parameterquelle für alle Speisen.'}
    ],
    chapters:[
      {id:'mechanismen',title:'1 · Welche Transportmechanismen wirken?',paragraphs:[
        'Diffusion entsteht aus mikroskopischer Teilchenbewegung und einem makroskopischen Antrieb wie einem Konzentrationsgefälle. Konvektion transportiert Stoff mit einer bewegten Flüssigkeit oder einem Gas. Beide Beiträge können gleichzeitig vorhanden sein. Ein steigender Messwert allein zeigt daher noch nicht, welcher Mechanismus dominiert.',
        'In porösen Körpern kann die Benetzung kapillare Druckunterschiede erzeugen. Dabei strömt Flüssigkeit durch zusammenhängende Poren. Das ist physikalisch von molekularer Diffusion zu unterscheiden. Ein vereinfachtes Diffusionsmodell kann die zeitliche Verteilung beschreiben, ohne die Porenströmung im Einzelnen aufzulösen.'
      ],equation:'Gesamttransport = diffusive Beiträge + Transport durch Bewegung des Mediums',detail:'Bei einer Modellwahl zuerst fragen, was transportiert wird: einzelne gelöste Spezies, Flüssigkeitsvolumen oder eine normierte Sättigung. Diese Größen haben unterschiedliche Einheiten und Bilanzgleichungen. Keks und Tee verwendet eine illustrative Sättigungsbeschreibung mit effektiven Parametern.',tools:['keks-und-tee'],sources:['mit','fisher']},
      {id:'fick',title:'2 · Fluss und zeitliche Konzentrationsverteilung',paragraphs:[
        'Das erste Fick’sche Gesetz setzt den diffusiven Stofffluss proportional zum negativen Konzentrationsgradienten. Das Minuszeichen beschreibt den Fluss in Richtung abnehmender Konzentration. Eine große Konzentrationsdifferenz über eine kurze Strecke kann daher einen stärkeren Fluss erzeugen als dieselbe Differenz über eine große Strecke.',
        'Die zeitliche Entwicklung folgt aus der Stoffbilanz. In einem ruhenden Medium ohne Quellen ergibt sich für konstanten Diffusionskoeffizienten die einfache Diffusionsgleichung. Bei orts- oder konzentrationsabhängigem D darf es nicht beliebig vor den Divergenzoperator gezogen werden.'
      ],equation:'J = −D ∇c;   ∂c/∂t = ∇·(D ∇c)',detail:'Bei c in mol/m³ und D in m²/s hat J die Einheit mol/(m²·s). In einer Sättigungsgleichung ist die Variable dagegen dimensionslos. Die Umrechnung einer Sättigungsänderung in aufgenommene Masse benötigt Volumen, Porosität und gegebenenfalls Flüssigkeitsdichte.',tools:['keks-und-tee'],sources:['comsol']},
      {id:'randbedingungen',title:'3 · Anfangs- und Randbedingungen bestimmen das Ergebnis',paragraphs:[
        'Eine Differentialgleichung allein legt den Verlauf noch nicht fest. Der Anfangszustand beschreibt die Verteilung zu Beginn. Randbedingungen geben vor, wie das System mit seiner Umgebung austauscht. Ein auf konstanter Konzentration gehaltener Rand verhält sich anders als ein Rand mit begrenztem Übergang oder eine abgedichtete Fläche.',
        'Beim Eintauchen ändern sich die benetzten Randflächen. Beim Herausziehen endet die äußere Flüssigkeitszufuhr im vereinfachten Modell. Anschließend kann sich die bereits aufgenommene Flüssigkeit weiter umverteilen. Eine lokale Änderung ist dann möglich, obwohl die Gesamtmenge konstant bleibt.'
      ],equation:'Abgedichteter Rand: J·n = 0;   Gesamtmenge: N = ∫ c dV',detail:'Die Gesamtbilanz ist eine wichtige Kontrolle. Ohne äußeren Fluss und ohne Quellen darf sich N nur durch numerische Fehler verändern. Bei normierter Sättigung muss die Mengenbilanz passend zu den Modellannahmen gewichtet werden.',tools:['keks-und-tee'],sources:['comsol']},
      {id:'zeitskalen',title:'4 · Warum die Größe des Körpers so wichtig ist',paragraphs:[
        'Eine charakteristische Diffusionszeit wächst mit dem Quadrat der Transportstrecke. Doppelte Dicke kann unter vergleichbaren Bedingungen ungefähr die vierfache Zeit erfordern. Der genaue Zahlenfaktor hängt von Geometrie, Randbedingungen und dem gewählten Kriterium ab.',
        'Winkel und Eintauchtiefe verändern beim Gebäckmodell die benetzte Fläche und die Wege zur übrigen Probe. Flüssigkeitsaufnahme und lokale Festigkeit entwickeln sich deshalb räumlich unterschiedlich. Ein einzelner Mittelwert kann solche Unterschiede verdecken.'
      ],equation:'tchar ≈ L² / D',detail:'L ist eine charakteristische Länge in m. Mit D in m²/s ergibt sich tchar in s. Die Abschätzung eignet sich zum Vergleichen ähnlicher Fälle; sie ersetzt keine Lösung für wechselnde Benetzung oder stark veränderliche Materialeigenschaften.',tools:['keks-und-tee'],sources:['timescale']},
      {id:'numerik',title:'5 · Diskretisierung, Sättigung und mechanische Folgen',paragraphs:[
        'Numerische Verfahren zerlegen einen Körper in Zellen und die Zeit in Schritte. Eine feinere Auflösung kann Gradienten besser erfassen, erhöht aber den Rechenaufwand. Ein stabiles Verfahren ist nicht automatisch ausreichend genau. Ergebnisse sollten daher bei veränderter Auflösung verglichen und gegen bekannte Grenzfälle geprüft werden.',
        'Die Kopplung an Aufweichen und Bruch benötigt zusätzliche Materialgesetze. Aus einem berechneten Flüssigkeitsfeld folgt nicht ohne Weiteres eine reale Bruchzeit. Bei Keks und Tee sind Speisendaten und Festigkeitsabnahme Lehrannahmen. Die Animation veranschaulicht den Modellverlauf und ist keine experimentelle Materialprüfung.'
      ],equation:'Prüfen: Massenbilanz, Wertebereich, Grenzfälle und Abhängigkeit von der Auflösung',detail:'In einem geschlossenen Nachverteilungsabschnitt soll die Gesamtmenge erhalten bleiben. Bei einer auf 0–1 normierten Sättigung sind Überschreitungen ein Warnzeichen. Reale Quellung, Rissbildung und Änderungen der Porenstruktur können andere Modelle erfordern.',tools:['keks-und-tee'],sources:['model']}
    ]
  },
  beschichtungen:{
    updated:'19. November 2026',
    intro:'Beschichtungen verbinden Werkstoffschutz, Applikation und Stofftransport. Dieser Lernweg erklärt Schutzwirkung und Versagen sowie Luftführung, Lackverbrauch und die stationäre Stoffbilanz beim Spritzlackieren.',
    sources:[
      {id:'solvent-limits',title:'TRGS 900 · Fassung 05.06.2026',url:'https://gewerbeaufsicht.baden-wuerttemberg.de/documents/20121/56990/5_900.pdf',role:'AGW und Kurzzeitinformationen für Aceton, Ethanol, Propan-2-ol, Ethylacetat, n-Butylacetat und Butanon. Einzelne UEG-Stoffquellen von GisChem, BG RCI und BG ETEM sind im Abluftrechner direkt bei den Stoffwerten dokumentiert; geprüft am 19.11.2026.'},
      {id:'ventilation',title:'DGUV Information 209-046 · Verarbeiten von flüssigen Beschichtungsstoffen',url:'https://publikationen.dguv.de/widgets/pdf/download/article/497',role:'Ausgabe Dezember 2024: technische Lüftung sowie Brand- und Explosionsschutz. Abschnitt 9 ordnet Luftführung und Orientierungsgeschwindigkeiten ein; keine vollständige Normprüfung durch das Tool.'},
      {id:'exposure',title:'BAuA · TRGS 402',url:'https://www.baua.de/DE/Angebote/Regelwerk/TRGS/TRGS-402.html',role:'Ermittlung und Beurteilung inhalativer Exposition, Gemischbewertung, Schicht- und Kurzzeitbezug sowie Anforderungen an nichtmesstechnische Verfahren.'},

      {id:'blister',title:'Blistering failure of elastic coatings with applications to corrosion resistance',url:'https://arxiv.org/abs/2106.13371',role:'Forschungsarbeit zu Blasenwachstum, mechanischer Verformung und Ablösung unter definierten Modellannahmen.'},
      {id:'iso',title:'ISO 4628-2 · Assessment of degree of blistering',url:'https://www.iso.org/standard/66399.html',role:'Die öffentliche Normbeschreibung erläutert den Vergleich mit bildlichen Standards. Für eine normbezogene Bewertung ist der vollständige anwendbare Normtext maßgeblich.'}
    ],
    chapters:[
      {id:'system',title:'1 · Schutzwirkung als Eigenschaft des gesamten Aufbaus',paragraphs:[
        'Ein Lackfilm kann den Stofftransport zur Oberfläche erschweren, eine Haftverbindung aufbauen und je nach System zusätzliche Schutzmechanismen besitzen. Entscheidend sind auch Vorbehandlung, Schichtdicke, Vernetzung, Poren und Kanten. Die Bezeichnung eines Bindemittels allein beschreibt deshalb nicht die Leistungsfähigkeit einer fertigen Beschichtung.',
        'Für belastbare Vergleiche sollten Probenaufbau und Prüfbedingungen dokumentiert werden. Unterschiedliche Substrate, Vorbehandlungen oder Trocknungsbedingungen können denselben sichtbaren Befund über verschiedene Wege erzeugen. Ein Foto zeigt zunächst das Erscheinungsbild, nicht eindeutig dessen Ursache.'
      ],equation:'Befund = beobachtete Erscheinung; Ursache = gesondert zu untersuchender Mechanismus',detail:'Eine zweckmäßige Dokumentation hält Probenkennung, Aufbau, betrachteten Bereich und Belastung fest. Eingeschränkte Bildqualität und fehlende Metadaten gehören zur Einordnung des Ergebnisses.',tools:[],sources:['blister']},
      {id:'blasen',title:'2 · Blasenbildung, Haftung und Ablösung',paragraphs:[
        'Blasen entstehen, wenn sich ein Film lokal vom Untergrund anhebt. Als treibende Größen kommen je nach System unter anderem Flüssigkeitsansammlung und Druck unter der Schicht in Betracht. Das Wachstum hängt zugleich von Haftung und mechanischen Eigenschaften des Films ab.',
        'Blasenbildung und flächige Ablösung sind verwandte, aber nicht identische Erscheinungen. Eine abgegrenzte Erhebung, eine offene Fehlstelle und ein zusammenhängend abgelöster Bereich sollten in der Bildauswertung verschiedene Befunde bleiben. Ihre geometrische Ausprägung kann sich im Verlauf einer Belastung ändern.'
      ],equation:'Blasenwachstum koppelt Druck, Filmverformung und Grenzflächenhaftung',detail:'Das verlinkte Forschungsmodell behandelt bestimmte mechanische und chemische Zusammenhänge. Daraus folgt keine universelle Kalibrierung eines Fotoalgorithmus und keine eindeutige Ursachendiagnose aus einem einzelnen Bild.',tools:[],sources:['blister']},
      {id:'begriffe',title:'3 · Entnetzung und andere sichtbare Fehlstellen sauber unterscheiden',paragraphs:[
        'Für eine nachvollziehbare Bewertung muss „Entnetzung“ eindeutig definiert werden: etwa als welche sichtbare Unterbrechung oder welcher freigelegte Flächenbereich. Sonst kann ein Algorithmus zwar reproduzierbare Pixel zählen, aber unterschiedliche Nutzer bewerten damit unterschiedliche Erscheinungen.',
        'Unterwanderung, Ablösung, Risse, Poren, Blasen und sichtbare Korrosionsprodukte können sich im Foto überlagern. Schatten einer Blase sind keine zweite Fehlstelle. Glanzreflexe können helle Flecken erzeugen, ohne dass Beschichtung fehlt. Eine fachlich nachvollziehbare Auswertung benötigt deshalb Regeln für Grenzfälle und eine Möglichkeit zur manuellen Kontrolle.'
      ],equation:'Erst Befundklasse und Zählregel definieren, dann Erkennung und Kennzahl',detail:'Befundklassen und Bewertungsregeln müssen vor einer Messung festgelegt sein. Dokumentierte Beispielbilder helfen dabei, Begriffe und Grenzfälle nachvollziehbar abzugrenzen.',tools:[],sources:['iso']},
      {id:'fotografie',title:'4 · Aufnahmebedingungen, Maßstab und Auswertefläche',paragraphs:[
        'Eine gleichmäßige Aufnahme erleichtert den Vergleich. Dazu gehören nachvollziehbarer Maßstab, möglichst unveränderte Beleuchtung und eine definierte Auswertefläche. Randbereiche, Markierungen und absichtlich eingebrachte Verletzungen sollten entsprechend dem Prüfziel ausdrücklich ein- oder ausgeschlossen werden.',
        'Eine in Pixeln gemessene Fläche wird erst mit einer geeigneten Kalibrierung zur physikalischen Fläche. Perspektive und gekrümmte Oberflächen verändern den Maßstab im Bild. Nachbearbeitung kann Kontraste beeinflussen und muss für reproduzierbare Auswertungen dokumentiert sein.'
      ],equation:'Flächenanteil = klassifizierte Fehlstellenfläche / ausgewertete Gesamtfläche',detail:'Der Quotient ist dimensionslos. Er sagt ohne zusätzliche Regeln nichts über Anzahl und Größe einzelner Blasen aus. Eine Probe kann bei gleichem Flächenanteil wenige große oder viele kleine Fehlstellen besitzen.',tools:[],sources:['iso']},
      {id:'bewertung',title:'5 · Bildkennzahlen, Normbezug und Validierung',paragraphs:[
        'Eine berechnete Kennzahl und eine normbezogene Bewertung sind verschiedene Schritte. Die öffentliche Beschreibung von ISO 4628-2 nennt den Vergleich des Blasengrads mit bildlichen Standards. Ein frei gewählter Flächenanteil ist daher nicht automatisch eine Bewertung nach dieser Norm.',
        'Für belastbare Bildbewertungen sind Vergleichsbilder mit unabhängiger fachlicher Bewertung hilfreich. Originalbild, markierte Befunde, gewählte Fläche und Bewertungsregeln sollten nachvollziehbar dokumentiert sein. Unsichere Befunde sind ausdrücklich als solche zu kennzeichnen.',
        'Eine beschleunigte Belastung dient einem festgelegten Prüfzweck. Aus einem einzelnen Bild nach einer bestimmten Belastungszeit lässt sich keine allgemeine Lebensdauer im Einsatz ableiten. Die Interpretation gehört immer zu Aufbau, Beanspruchung und Beurteilungsregeln.'
      ],equation:'Dokumentieren → auswerten → visuell kontrollieren → gegen Referenz bewerten',detail:'Prüfdurchführung, Grenzwerte und Freigaben richten sich nach dem konkreten Anwendungsfall. Die Theorie ersetzt weder einen vollständigen Normtext noch die unabhängige fachliche Prüfung eines Befundes.',tools:[],sources:['iso','blister']}
      ,{id:'luftfuehrung',title:'6 · Luftführung, Arbeitsquerschnitt und Ansaugöffnung',paragraphs:[
        'Eine Absaugung muss Spritznebel und Dämpfe wirksam erfassen. Die Position von Werkstück, Bedienperson und Zuluft beeinflusst das reale Strömungsbild. Eine Luftwechselzahl allein belegt keine Erfassung am Entstehungsort. Die Lage des Werkstücks und die Richtung der Luftführung sind getrennte Angaben.',
        'Eine Wasserwand kann die Luft über einen unteren Spalt ansaugen. Benetzte Wandfläche, freie Spaltfläche und Arbeitsquerschnitt sind dann verschiedene Größen. Bei Trockenabsaugungen ist die projizierte aktive Filterfront von der entfalteten Filtermedienfläche zu unterscheiden. Kabinen mit Luftführung nach unten besitzen einen horizontalen Bezugsquerschnitt.'
      ],equation:'Q = 3600 A v; ASpalt = bSpalt hSpalt; n = Q / VRaum',detail:'Q in m³/h, A in m², v in m/s und n in h⁻¹. Bei gleichem Volumenstrom erzeugt ein kleinerer Spalt eine höhere Eintrittsgeschwindigkeit. Daraus folgt keine ausreichende Geschwindigkeit am Werkstück. Die SVG-Kabinen zeigen schematische Luftwege; keine CFD, Druckverluste oder Wirbelberechnung. Alle Kabinenmaße und Startvolumenströme sind frei einstellbare Lehrannahmen. Es werden keine Herstellerwerte oder -baugrößen verglichen.',tools:['abluftrechner'],sources:['ventilation']},
      {id:'lackbilanz',title:'7 · Spritzfertiger Lack, flüchtige Anteile und Auftragswirkungsgrad',paragraphs:[
        'Die Stofflast folgt aus Lackdurchsatz, Nasslackdichte und Massenanteilen des spritzfertigen Gemischs einschließlich Härter und Verdünner. Wasser und organische Lösemittel werden getrennt bilanziert. Volumenfestkörper und Massenfestkörper sind unterschiedliche Angaben und dürfen nicht gleichgesetzt werden.',
        'Bei festem Pistolen-Durchsatz verändert ein höherer Auftragswirkungsgrad zunächst die Verteilung zwischen Werkstück und Verlusten. Die eingebrachte Lösemittelmenge bleibt dabei gleich. Für einen festgelegten Auftrag auf dem Werkstück kann ein höherer Wirkungsgrad dagegen den benötigten Lackdurchsatz verringern. Im vereinfachten Modell wird dabei gleiche Zusammensetzung ohne Vorverdunstung angenommen.'
      ],equation:'ṁLack = V̇Lack ρ; ṁi = ṁLack wi; bei festem Auftragsziel: V̇Pistole = V̇Auftrag / η',detail:'Einheiten konsistent umrechnen: ml/min × 60/1000 ergibt l/h; mit kg/l folgt kg/h. RP oder HVLP allein bestimmen weder den tatsächlichen Wirkungsgrad noch einen pauschalen Abluftfaktor. Die Vorlage verwendet 65 % als einstellbare Lehrannahme, nicht als zugesicherte Prozesskennzahl. Aerosole bleiben auch ohne organische Lösemittel relevant.',tools:['abluftrechner'],sources:['ventilation']},
      {id:'stoffbilanz-luft',title:'8 · Stationäre Verdünnung und Grenzen der Stoffbewertung',paragraphs:[
        'Eine stationäre Stoffbilanz setzt Freisetzung und Abtransport ins Verhältnis. Im einfachsten Fall sind Zuluft unbelastet und der betrachtete Raum vollständig durchmischt. Der Rechner behandelt alle eingegebenen organischen Lösemittel kontinuierlich als in diesem Bereich freigesetzt. Das ist keine gemessene Verdunstungskinetik.',
        'Gesundheitsschutz und Explosionsschutz benötigen getrennte Betrachtungen. Für einen idealisierten AGW-Modellvergleich werden Stoffindizes addiert. Die UEG-Rechnung verwendet eine additive Gemischnäherung für Lösemitteldämpfe. Ohne vollständige Stoffdaten bleibt die jeweilige Bewertung offen; die Geometrie allein bestätigt keinen sicheren Betrieb. Sechs Lösemittel sind mit AGW, UEG, CAS und Quellen auswählbar. Änderungen an hinterlegten Werten werden als Benutzerwerte gekennzeichnet.'
      ],equation:'QAGW,ideal = Σ(ṁi / AGWi); QUEG,Vergleich = k Σ(ṁi / UEGi) / fUEG',detail:'Für AGW werden mg/h und mg/m³ verwendet, für UEG g/h und g/m³. Stoffanteile beziehen sich auf den gesamten spritzfertigen Lack. Die reale Bewertung muss Schichtmittelwerte, Kurzzeitspitzen, weitere Gefahrstoffe und örtliche Belastungen berücksichtigen. Brennbare Sprühnebel werden durch die Lösemittel-UEG-Rechnung nicht bewertet. Für den UEG-Modellvergleich ist ein Zuschlagsfaktor einstellbar; Startwert 3 stammt aus dem DGUV-Rechenbeispiel in Anhang 1. Die zusätzliche Warnschwelle von 80 Prozent ist eine frei gewählte Modelleinstellung. Eine Kurzzeitinformation aus TRGS 900 ist keine Prüfung ihrer zeitlichen Einhaltung. Keine Anlagenfreigabe, Zoneneinteilung oder Gefährdungsbeurteilung.',tools:['abluftrechner'],sources:['exposure','ventilation','solvent-limits']}

    ]
  },
  werkstofftechnik:{
    intro:'Werkstofftechnik verbindet Zusammensetzung, Herstellung, Gefüge und Eigenschaften. Am Beispiel der Stahl-Wärmebehandlung führt dieser Lernweg vom Gleichgewicht zu zeitabhängigen Umwandlungen und zu räumlichen Temperaturunterschieden im Bauteil.',
    sources:[
      {id:'atlas-heine',title:'Burkhard Heine · Hochschule Aalen',url:'https://www.hs-aalen.de/person/burkhard-heine/',role:'Lehrinhalte zu binären und ternären Gleichgewichten, Phasenumwandlungen und Modellierung; didaktische Einordnung der Atlasdarstellung.'},
      {id:'atlas-bipbsn',title:'NIST · Bi–Pb–Sn',url:'https://www.metallurgy.nist.gov/phase/solder/bipbsn.html',role:'Bewertetes ternäres Vergleichssystem mit Eutektikum bei 98,0 °C und Übergangsreaktion bei 135,7 °C; enthält zusätzlich ε-Pb.'},
      {id:'steel-cementite',title:'Vogric et al. · Kinetic Modeling of Grain Boundary Cementite Evolution (2022)',url:'https://doi.org/10.1007/s11661-022-06784-1',role:'Primärarbeit zu Korngrenzenzementit, Grenzflächenhemmung und erforderlicher Validierung. Mechanistische Grundlage; die eigenen Lehrzeitkonstanten sind nicht daraus kalibriert.'},
      {id:'atlas-bargel',title:'Bargel/Siemer · Werkstoffkunde, 14. Auflage',url:'https://doi.org/10.1007/978-3-662-71672-4',role:'Abschnitte 1.3 und 1.6 erläutern Keimbildung, Erstarrungsformen, Gefügebestandteile und Nichtgleichgewicht; Grundlage der schematischen Einordnung, keine vollständige thermodynamische Datenbank.'},
      {id:'atlas-agbisn',title:'NIST · Ag–Bi–Sn',url:'https://www.metallurgy.nist.gov/phase/solder/agbisn.html',role:'Aus binären Beschreibungen extrapoliertes ternäres Modell und publizierte Reaktionen. Modellvorhersage und experimentelle Bewertung unterscheiden.'},
      {id:'atlas-bicusn',title:'NIST · Bi–Cu–Sn',url:'https://www.metallurgy.nist.gov/phase/solder/bicusn.html',role:'Extrapoliertes Lotmodell mit Cu–Sn-Verbindungen. Keine experimentelle Vollbewertung des gesamten ternären Raums.'},
      {id:'atlas-cost507',title:'COST507 · freie Datenbank für Leichtmetalle',url:'https://www.opencalphad.com/databases.php',role:'Round II (1999): ternäre Bewertungen für Al–Mg–Si und Al–Cu–Mg; Al–Cu–Si ohne ternäre Wechselwirkungsparameter. Ältere Modellgeneration mit dokumentierter Parseranpassung.'},
      {id:'atlas-agpbsn',title:'NIST · Ag–Pb–Sn',url:'https://www.metallurgy.nist.gov/phase/solder/agpbsn.html',role:'Binär extrapoliertes Lotmodell mit drei tabellierten invarianten Reaktionen und Schmelzgehalten.'},
      {id:'atlas-storage',title:'Villada et al. (2022) · MgCl₂–KCl–NaCl',url:'https://doi.org/10.3389/fenrg.2022.809663',role:'Originalarbeit mit farbigen Isothermen und getrennten DSC-Onset-/Endwerten; Grundlage des geometrischen NaCl–KCl–MgCl₂-Übersichtsmodells.'},
      {id:'atlas-sgte',title:'Hallstedt (2025) · SGTE binary collection',url:'https://doi.org/10.1016/j.calphad.2025.102833',role:'Offene CC-BY-4.0-Parameterdateien; unveränderte Originalbewertungen für Al–Si, Al–Cu und Cu–Ni mit Herkunftsnachweis im Repository.'},
      {id:'atlas-alsi',title:'Liang und Schmid-Fetzer (2014) · Al–Si-Teilsystem',url:'https://doi.org/10.1016/j.actamat.2014.02.042',role:'Bewerteter Al–Si-Datensatz im Rahmen der Untersuchung von Phosphor in Al–Si-Gusslegierungen; keine Kalibrierung der schematischen Si-Morphologie.'},
      {id:'atlas-alcu',title:'Witusiewicz et al. (2004) · Al–Cu-Teilsystem',url:'https://doi.org/10.1016/j.jallcom.2004.04.126',role:'Bewertung des Al–Cu-Randsystems; metastabiles θ′ wird im Atlas ausgeschlossen. Keine Ausscheidungskinetik.'},
      {id:'atlas-cuni',title:'an Mey (1992) · Cu–Ni',url:'https://doi.org/10.1016/0364-5916(92)90022-P',role:'Thermodynamische Bewertung einschließlich magnetischer Beiträge und des weniger sicher belegten Tieftemperaturbereichs.'},
      {id:'atlas-nist',title:'NIST · Solder phase diagrams and thermodynamic database',url:'https://www.metallurgy.nist.gov/phase/solder/solder.html',role:'Bewertete thermodynamische Modelle, Phasenzusammensetzungen und Reaktionen für die Metallmodelle des Atlas.'},
      {id:'atlas-robelin',title:'Robelin, Chartrand und Pelton (2004) · NaCl–KCl–AlCl₃',url:'https://doi.org/10.1016/j.jct.2004.04.011',role:'Stoffdaten und optimierte quasichemische Wechselwirkungsparameter; Abb. 18 liefert den quasibinären Prüffall NaAlCl₄–KAlCl₄. Das geometrische Isothermenmodell ist eine zusätzliche Übersichtsnäherung; der vollständige quasichemische Modellformalismus ist noch nicht umgesetzt.'},
      {id:'atlas-microstructure',title:'Moon et al. · Experimental and thermodynamic assessment of Sn–Ag–Cu',url:'https://www.msed.nist.gov/phase/papers/JEM%28Sn-Ag-Cu%29.pdf',role:'Experimentelle Phasen- und Gefügebeobachtungen für das Lotbeispiel. Keine Kalibrierung der schematischen Atlasbilder.'},
      {id:'atlas-salt',title:'ORNL/SPR-2021/2102 · Molten Salt Thermal Properties Database',url:'https://info.ornl.gov/sites/publications/Files/Pub161288.pdf',role:'Abb. 6 belegt den Salzschnitt bei 40 mol-% AlCl₃ und 1 bar.'},
      {id:'mit',title:'MIT OpenCourseWare · Thermodynamics and Kinetics of Materials',url:'https://ocw.mit.edu/courses/3-205-thermodynamics-and-kinetics-of-materials-fall-2006/pages/lecture-notes/',role:'Lehrmaterial zu Diffusion, Keimbildung, Wachstum und Zeit-Temperatur-Umwandlung.'},
      {id:'heat',title:'Lienhard & Lienhard · A Heat Transfer Textbook',url:'https://ahtt.mit.edu/wp-content/uploads/2019/08/AHTTv500.pdf',role:'Vertiefendes Lehrbuch zu Wärmeleitung, Energiebilanz und Wärmeübergang.'},
      {id:'cambridge',title:'University of Cambridge · Phase transformations teaching materials',url:'https://www.phase-trans.msm.cam.ac.uk/teaching.html',role:'Vertiefende Lehre zu Umwandlungen und Gefügen in Stählen. Keine Kalibrierung der Werkzeugdeck-Lehrparameter.'}
    ],
    chapters:[
      {id:'aluminium-und-chloride',title:'Aluminium, Cu–Ni und rekonstruierte Chlorid-Isothermen',paragraphs:[
        'Al–Si, Al–Cu und Cu–Ni verwenden offene bewertete Gibbs-Parameter aus der SGTE-Sammlung von Hallstedt. Ihre Phasenmengen werden mit derselben diskreten unteren Gibbs-Hülle bestimmt wie die Lotmodelle. Die zusätzliche direkte Liquidusrechnung liefert glatte binäre Grenzlinien, ohne ideale Mischungen oder frei gewählte Linsenformen anzunehmen.',
        'Al–Si verbindet Primär-Al und Primär-Si mit eutektischer Erstarrung. Al–Cu enthält θ-Al₂Cu und weitere Cu-reiche Phasen; θ′ wird als metastabile Phase ausgeschlossen. Ausscheidungsabfolge, Teilchengröße, Veredelung und Härte benötigen zusätzliche Prozess- und Kinetikmodelle. Cu–Ni enthält magnetische Beiträge; mögliche feste Entmischung im Tieftemperaturbereich stammt aus der gewählten Bewertung und ist dort weniger sicher als die Schmelzlinse.',
        'Das NaCl–KCl–MgCl₂-Modell rekonstruiert die farbigen Isothermen und näherungsweisen Reaktionsgrenzen aus Abb. 4 von Villada et al. Überlagerte Markierungen und konstante Farbbänder werden geglättet. Die Untergrenze des publizierten Projektionsminimums beträgt 385,4 °C. Die Begrenzung kann breite Talbereiche erzeugen; eine experimentell abgesicherte Fehlergrenze der Rekonstruktion ist nicht bestimmt.',
        'Chloridverbindungen dienen als feste Bilanzpunkte. Na/K-Varianten werden zu angenommenen linearen Mischkristallfamilien zusammengefasst; NaCl/KCl nutzt zusätzlich die benannte binäre Mischungsnäherung. Maximal geometrisch zulässige Restschmelze erhält Komponenten und Masse, ist aber keine Gibbs-Minimierung. Wärmeabfuhrmaß und Gefügebilder bleiben schematisch.',
        'Die fünf DSC-Zusammensetzungen mit Onset- und Endtemperaturen bei 10 K/min sind eigene Vergleichsziele. Sie werden nicht dem Projektionsminimum gleichgesetzt. Gas, Wasser, Hydrolyse und Korrosion fehlen im Modell; aus dem berechneten Schmelzbereich folgt keine technische Freigabe eines Salzwärmespeichers.'
      ],equation:'Gehaltsdreieck + Isothermen + benannte Bilanzannahmen → geometrisches Übersichtsmodell',detail:'90 separate Direktzustände und 60 zusätzliche Grenzprüfzusammensetzungen prüfen die neuen binären Stoffrechnungen gegen dieselben Parameter. Die Salzprüfung betrifft Bilanz und Verlaufskonsistenz, keine experimentell validierte Phasenmengenprognose.',tools:['legierungsatlas'],sources:['atlas-sgte','atlas-alsi','atlas-alcu','atlas-cuni','atlas-storage','atlas-robelin']},
      {id:'ternary-aluminium',title:'Ternäre Aluminium-Systeme und Lotvergleich',paragraphs:[
        'Al–Mg–Si und Al–Cu–Mg verwenden die ternären COST507-Bewertungen (Round II, 1999). Mg₂Si und S-Al₂CuMg sind auswählbare Verbindungsgehalte für Schnitte und Vergleichspunkte. Die Schnittwahl allein ist kein Nachweis exakter Quasibinarität. Die ternären Ränder verwenden ältere Bewertungen und können von den separaten Al–Si-/Al–Cu-Modellen abweichen.',
        'Al–Cu–Si enthält in COST507 keine ternären Wechselwirkungsparameter und wird aus den binären Rändern extrapoliert. Ag–Pb–Sn ist ebenfalls eine ausdrücklich binäre Extrapolation nach NIST. Literaturpunkte sind Vergleichsziele und erzwingen keine Anpassung der Modellflächen.',
        'In den vier neuen ternären Modellen werden Beiträge unter 0,2 mol-% für Phasenfeldnamen als numerische Spuren geführt; die berechneten Mengen bleiben vollständig erhalten. Die Anschmelzlinie wird separat aus direkten Gleichgewichten mit phasenabhängigen C1-Radialbasisfunktionen rekonstruiert. Die Mengenabweichung kann in den geprüften Zuständen mehrere Prozentpunkte betragen.',
        'Nur kondensierte Gleichgewichtsphasen sind aktiv. Gas und metastabiles θ′ werden ausgeschlossen. β″/β′ und S′, Alterung, Ausscheidungsgrößen und Festigkeit benötigen eigene kinetische Modelle; die vorhandenen Gefügebilder sind illustrative Skizzen.'
      ],equation:'Gleichgewichtsphase ≠ härtende Ausscheidung ≠ Gefügemorphologie',detail:'Glatte Liquidus- und Anschmelzflächen stammen aus direkten Gleichgewichten mit phasenabhängiger Interpolation. 192 zusätzliche Direktzustände und 48 Gehalte mit je zwei Grenzprüfungen vergleichen die Rekonstruktion mit derselben Gibbs-Datenbasis. In dieser Stichprobe höchstens 4,17 Prozentpunkte Mengenabweichung, 5,86 K am Anschmelzen und 3,01 K am Liquidus; keine experimentelle Gesamtgenauigkeit.',tools:['legierungsatlas'],sources:['atlas-cost507','atlas-agpbsn']},
      {id:'systembibliothek',title:'Stoffsysteme auswählen und ihre Datengüte einordnen',paragraphs:[
        'Der Atlas enthält 31 Stoffsysteme: 16 binäre Metallsysteme, fünf binäre Salzsysteme, acht ternäre Metallsysteme und zwei ternäre geometrische Chloridmodelle. Die zwölf zusätzlichen Binärpaare Ag–Bi, Bi–Cu, Ag–Pb, Al–Mg, Mg–Si, Cu–Si, Cu–Mg, NaCl–KCl, NaCl–MgCl₂, KCl–MgCl₂, NaCl–AlCl₃ und KCl–AlCl₃ werden aus den vorhandenen ternären Randberechnungen übernommen. Alle Metallzustände werden lokal aus vorbereiteten Gibbs-Energie-Hüllen abgefragt; eine zusätzliche Serverrechnung ist nicht nötig.',
        'Ag–Cu ist ein gut lesbarer Einstieg in das eutektische Erstarren mit zwei festen Mischkristallen. Ag–Sn ergänzt die zinnhaltigen Lote um Ag₃Sn und Peritektika. Pb–Sn dient als klassischer eutektischer Vergleich. Bi–Pb zeigt zusätzlich ε-Pb und eine peritektische Reaktion. Die vier ergänzten binären NIST-Beschreibungen sind thermodynamisch bewertet.',
        'Ag–Bi–Sn und Bi–Cu–Sn sind laut NIST ternäre Extrapolationen bewerteter binärer Beschreibungen. Sie erlauben den Vergleich von Bi-haltigen Loten und intermetallischen Phasen; eine gute numerische Übereinstimmung mit dem eigenen Gibbs-Modell ist keine unabhängige experimentelle Validierung dieser Extrapolation.',
        'Literaturmarkierungen geben die veröffentlichte Schmelzzusammensetzung und Reaktionstemperatur an. Die aktuelle NIST-Beschreibung nennt beispielsweise 182,2 °C für das Pb–Sn-Eutektikum; das darf nicht ungeprüft mit anderen tabellierten Werkstoffwerten gleichgesetzt werden. Die Einrastziele und Komponentenreihenfolge gehören zum jeweiligen System.',
        'Für spätere Modelle bleiben Al–Mg–Si und Al–Cu–Si (Aluminium), Cu–Zn (Messing) und Fe–C/Fe–Fe₃C (Stahl und Gusseisen) besonders interessant. Die Auswahlhilfe im Tool verlinkt Quellen und benennt fehlende Daten.',
        'Geometrische Isothermenmodelle sind für die Übersicht möglich. Zusätzlich werden Primärfelder, Reaktionslinien und Verbindungsgehalte benötigt. Eindeutige Phasenanteile erfordern Konoden oder ergänzende Bilanzregeln; Abkühlzeiten benötigen thermische Daten. Ausscheidungshärtung, Bainit und Martensit benötigen außerdem metastabile Zustände beziehungsweise Kinetik.'
      ],equation:'Bewertetes Binärmodell ≠ experimentell bewertetes ternäres System',detail:'Neue Systeme werden erst mit berechenbaren Endpunkten, positiver Mengenbilanz, konsistenter Prozentbasis und Prüfzuständen in die aktive Bibliothek aufgenommen. Zukünftige Kandidaten bleiben von den auswählbaren Stoffmodellen getrennt.',tools:['legierungsatlas'],sources:['atlas-nist','atlas-agbisn','atlas-bicusn','atlas-storage']},
      {id:'isothermen-modell',title:'Geometrisches Salzmodell, glatte Anschmelzgrenze und feste Anker',paragraphs:[
        'Eine Liquidusprojektion liefert Temperaturen, Primärgebiete und Reaktionslinien. Ohne weitere Angaben bestimmt sie weder alle Konoden noch eindeutige Phasenanteile oder Wärmeabfuhrzeiten. Für eine schematische Rekonstruktion müssen diese zusätzlichen Regeln ausdrücklich angegeben werden.',
        'Das NaCl–KCl–AlCl₃-Modell verwendet 343 numerische Isothermenstützstellen aus Robelin et al., Abb. 21, sowie Verbindungen und eutektische Referenzpunkte aus Tabelle 6. Formtreue Profile entlang fester Alkalisalzverhältnisse verbinden die geometrisch beruhigten Quellisothermen. In zwischen gleichen Isothermen eingeschlossenen Tälern wird eine begrenzte Talform innerhalb des benachbarten 25-K-Abstands angenähert. Die genaue Zwischenkonturform ist damit eine Annahme.',
        'Die geometrische Mengenregel wählt den größtmöglichen Schmelzanteil auf einer zulässigen Isothermenzerlegung mit festen Endgliedern NaCl, KCl, NaAlCl₄, KAlCl₄ und AlCl₃. Komponenten- und Massenbilanz bleiben erfüllt. Die Aufteilung der vorhandenen NaCl/KCl-Festanteile nutzt näherungsweise die veröffentlichte binäre Überschussenergie für einen oder zwei Mischkristalle. Das ersetzt keine vollständige Gibbs-Energie-Minimierung im ternären Salzsystem. Spuren unter 0,3 Prozent und Einzelspalten werden in den schematischen Feldnamen beruhigt; die Mengenwerte bleiben getrennt.',
        'Die Salz-Abkühlkurve zeigt ein normiertes Wärmeabfuhrmaß aus einem sensiblen Anteil und einem angenommenen latenten Gewicht 0,6. Ohne Wärmekapazitäten und Erstarrungsenthalpien folgen daraus keine Sekunden oder kJ/mol. Oberhalb 74 mol-% AlCl₃ reicht die Datendeckung nicht aus; die Spitze bleibt grau. Gas und Flüssig–Flüssig-Entmischung werden nicht berechnet. Alle Zustände beziehen sich auf kondensierte Modellphasen.',
        'Die Metall-Anschmelzgrenze wird zusätzlich durch direkte Flüssigauftretens-Gleichgewichte bestimmt. Getrennte Äste für verschiedene feste Phasenbestände erhalten echte Reaktionssprünge. Gemeinsame geglättete Feldränder verhindern widersprüchliche Grenzen benachbarter Felder. Eine ruhige Darstellung ist eine Interpolation, keine höhere Stoffdatengenauigkeit.',
        'Anker A₁/A₂ liegen im Gehaltsdreieck. Ein Anker hält die Schnittgerade durch ein Ziel und erlaubt die Drehung darum. Zwei verschiedene Anker legen die Gerade fest. S₁/S₂ sind ihre Randintersektionen; X-Punkte bleiben entlang der Geraden verschiebbar. Die rote Schnittliquiduslinie in 3D benutzt dieselbe Fläche und folgt der veränderten Schnittebene.'
      ],equation:'x₀ = fL xL + Σᵢ fᵢ xᵢ;  fL + Σᵢ fᵢ = 1;  geometrische Annahme: fL maximal',detail:'96 zusätzliche Direktrechnungen prüfen die phasenabhängige Metall-Anschmelzdarstellung gegen dasselbe Stoffmodell. Die maximale Abweichung in dieser Stichprobe beträgt etwa 5,88 K für Ag–Cu–Sn und 0,88 K für Bi–Pb–Sn. Die geometrischen Salzmengen besitzen keine entsprechende thermodynamische Validierung; sie sind ein transparentes Übersichtsmodell.',tools:['legierungsatlas'],sources:['atlas-nist','atlas-robelin','atlas-bipbsn']},
      {id:'liquidus-konstruktion',title:'Liquidusfläche, Reaktionslinien und geometrische Bilanz',paragraphs:[
        'Die drei binären Randdiagramme bilden die Seiten des ternären Temperaturprismas. Die Liquidusfläche begrenzt den vollständig flüssigen Raum. Ihre Isothermen sind Höhenlinien derselben Fläche; sie dürfen nicht unabhängig so verschoben werden, dass neue Minima oder Kreuzungen entstehen. Die 3D-Ansicht des Atlas zeigt die binären Phasenfelder als ausblendbare Seitenflächen und richtet die gewählte Randseite nach vorne aus.',
        'Im Atlas werden mehr als 2000 Liquidustemperaturen je ternärem System durch direkte Flüssig-Fest-Sättigung bestimmt: Die feste Phase hat null Anteil, die Temperatur wird frei gelöst. Vollständige Gleichgewichte beidseits prüfen den Übergang. Eine stetig differenzierbare Clough–Tocher-Interpolation liefert eine gemeinsame Darstellungsfläche für Dreieck, 3D und Schnittliquidus. Sie kann sehr schmale Knicke verrunden. Die Mengenrechnung verwendet weiterhin die diskrete Gibbs-Hülle.',
        'Reaktionslinien verbinden Grenzen benachbarter Primärgebiete. Ihre Pfeile zeigen lokal zu tieferen Temperaturen; bei einem Maximum können sie zu verschiedenen Endpunkten weisen. Die Atlaslinien werden aus den Sättigungszweigen und direkt belegten Primärgebieten rekonstruiert und geometrisch beruhigt. Sie sind keine vollständige exakte Verfolgung aller univarianten Gleichgewichte. E bezeichnet ein ternäres Eutektikum L → α + β + γ, P eine ternäre peritektische Reaktion L + α + β → γ und U eine Übergangsreaktion L + α → β + γ.',
        'Bei drei Phasen beschreibt das Konodendreieck die möglichen Gesamtzusammensetzungen. Die baryzentrischen Gewichte sind molare Phasenanteile. Das Gewicht einer Ecke entspricht der gegenüberliegenden Teilfläche geteilt durch die Gesamtfläche. Bei zwei Phasen gilt das Hebelgesetz entlang der Konode. Massenanteile entstehen erst durch Umrechnung mit den mittleren molaren Massen der Phasen. Gefügebestandteile sind damit noch nicht geometrisch bestimmt.',
        'Die Achsen hängen von der ausdrücklichen Bereichswahl ab, nicht vom Temperaturzeiger. Der automatische Schnittbereich umfasst alle erkannten Phasenwechsel mit Abstand zur unteren und oberen Grenze. Abkühlkurven zeigen immer den gesamten berechneten Temperaturverlauf. Endet das Stoffmodell an einer Temperaturgrenze, werden darunter keine Phasenfelder erfunden.'
      ],equation:'x₀ = Σᵢ fᵢ xᵢ;  Σᵢ fᵢ = 1;  fᵢ ≥ 0',detail:'Die unabhängige numerische Liquidusprüfung an 70 zusätzlichen Zusammensetzungen ergibt in diesen Fällen höchstens 1,24 K Abweichung für Ag–Cu–Sn und 0,47 K für Bi–Pb–Sn gegenüber direkter Rechnung mit demselben Stoffmodell. Das ist keine experimentelle Validierung. Literaturmarkierungen geben Schmelzzusammensetzungen und Literaturtemperaturen an; sie bleiben von interpolierten Modellgrenzen unterscheidbar. Ein widersprüchlicher NIST-Tabelleneintrag bei 640,1 °C wird nicht als Einrastziel verwendet.',tools:['legierungsatlas'],sources:['atlas-nist','atlas-bipbsn','atlas-heine','atlas-bargel']},
      {id:'binaere-raender',title:'Binäre Randsysteme aus ternären Modellen',paragraphs:[
        'Auf einer Dreiecksseite ist der Anteil der dritten Komponente null. Der Randrechner fragt genau diesen Zustand im vorhandenen ternären Modell ab und projiziert die Phasenzusammensetzungen auf die beiden verbleibenden Komponenten. Die Mengenbilanz, Enthalpie und Datenbasis werden übernommen; es wird kein neues ideales Binärmodell angenommen. Metallränder werden als kompakte eindimensionale Hüllen aus den vorhandenen Randfacetten bereitgestellt; der Browser lädt dafür keinen vollständigen ternären Datensatz.',
        'Jedes Gehaltsdreieck bietet drei direkte Verknüpfungen zu seinen binären Stoffpaaren. Für bereits eigenständig bewertete Binärsysteme bleibt die vorhandene Bewertung maßgebend. Eine ältere ternäre Randbeschreibung kann davon abweichen; die Quelle steht bei der Auswahl. Je Stoffpaar wird ein Referenzmodell angeboten, um die Bibliothek übersichtlich zu halten.',
        'Die fünf Salzränder bleiben geometrische Isothermenmodelle mit den bisherigen Annahmen. Die Achse reicht bis zu beiden Reinstoffen; jenseits 74 mol-% AlCl₃ sind jedoch keine belegten Modelldaten vorhanden. Der Bereich wird schraffiert und liefert keine erfundenen Phasenmengen, Gefüge oder Schmelzlinien.'
      ],equation:'xC = 0; xA + xB = 1; x₀ = Σ fᵢ xᵢ',detail:'Die Randübernahme wird gegen Zustände derselben ternären Quelle sowie Komponenten- und Massenbilanzen geprüft. Das belegt die konsistente Wiederverwendung des Modells und ist keine unabhängige experimentelle Validierung.',tools:['legierungsatlas'],sources:['atlas-nist','atlas-cost507','atlas-robelin','atlas-storage']},
      {id:'phasendiagramme',title:'Phasendiagramme, Gehaltsschnitte und Zusammensetzungsbasis',paragraphs:['Liquidus-Isothermen in einer Projektion verbinden Zusammensetzungen mit gleicher Temperatur des Erstarrungsbeginns. Ein isothermer Schnitt zeigt dagegen die Phasenfelder bei einer festen Temperatur. Konoden verbinden die Zusammensetzungen koexistierender Phasen. In einem ternären System kann ein Gehaltsschnitt Phasen enthalten, deren Zusammensetzungen außerhalb der gewählten Schnittebene liegen.','Der Gesamtgehalt einer Probe bleibt beim Abkühlen konstant. Die Restschmelze ändert dagegen ihre Zusammensetzung. Phasenanteile folgen aus der Stoffbilanz. Ein Eutektikum kann die letzte Restschmelze verbrauchen; bei einer peritektischen Reaktion hängt das Ende davon ab, welcher Reaktionspartner zuerst verbraucht ist.','Stoffmengen- und Massenanteile beschreiben denselben Stoffbestand mit unterschiedlichen Bezugsgrößen. Bei Metallen beziehen sich Stoffmengen auf die Elemente, bei der Salzreferenz auf die wasserfreien Salzkomponenten. Phasenanteile und Komponentengehalte müssen getrennt angegeben werden.','Die drei Achsen eines Gehaltsdreiecks zeigen jeweils den Anteil einer anderen Komponente; ihre Summe ist 100 %. Schnittendpunkte S₁/S₂ sind ebenfalls Gesamtzusammensetzungen und können mit X-Punkten verglichen werden. Die drehbare 3D-Liquidusfläche zeigt die Temperatur des vollständigen Aufschmelzens über dem Dreieck. Ihre binären Randkurven liegen auf den Seiten des Temperaturprismas. Diese Ansicht ist noch keine Darstellung aller Phasenvolumina. Phasenanteile lassen sich als Einzelkurven oder gestapelte Flächen lesen. Die gemeinsame Ablesetemperatur bestimmt Zahlenwerte, Phasenzustände und Gefügeskizze. Angezeigte Linien sind geglättete Konturen; einblendbare Konturstützstellen und numerische Grenzintervalle machen die Auflösung sichtbar.','Für NaCl–KCl–AlCl₃ liefert Robelin et al. (2004) die Stoffdaten und Modellparameter. Im quasibinären Teilsystem NaAlCl₄–KAlCl₄ liegt das berechnete Eutektikum laut Abb. 18 bei 133,2 °C und 27,8 mol-% KAlCl₄; gegenseitige feste Löslichkeit wird dort vernachlässigt. Der Atlas ergänzt nun eine geometrische Übersicht aus den Literaturisothermen. Eine vollständige quasichemische Salz-Gleichgewichtsrechnung ist damit weiterhin nicht umgesetzt.','Beide Reinstoffenden gehören zum Zustandsdiagramm. Beim Reinstoff können fest und flüssig am Schmelzpunkt koexistieren. Die Anschmelzgrenze einer Legierung bezeichnet den Beginn der Bildung von Schmelze beim Erwärmen. Eine technisch zulässige Einsatztemperatur erfordert zusätzlich Belastung, Zeit und Umgebung.'],equation:'wᵢ = xᵢ Mᵢ / Σⱼ(xⱼ Mⱼ);  Σₚ fₚ xᵢ,ₚ = xᵢ,gesamt',detail:'Der Legierungsatlas berechnet die Mengenbilanz lokal auf einer diskreten unteren Gibbs-Energie-Hülle aus veröffentlichten NIST-Phasenmodellen. Regelmäßige Zusammensetzungsstützstellen werden durch direkt optimierte Gleichgewichtsstützstellen ergänzt. Die Gibbs-Energie eines homogenen Mittelpunktes entscheidet, welche Stützstellen als eine Phase zusammengefasst werden. So bleiben echte Entmischungsgebiete erhalten, während künstliche Mehrfach-Schmelzphasen aus einem groben Raster vermieden werden. Die Grenzschätzung verwendet den gesamten Flüssig-/Festanteil. Zusammensetzungsstützstellen und Temperaturintervalle begrenzen weiterhin die numerische Genauigkeit. Eine Visualisierung der Phasenanteile liefert noch keine quantitative Korngrößen- oder Gefügeprognose. Für den Salzschnitt gelten die ausdrücklich angegebenen Referenzbedingungen.',tools:['legierungsatlas'],sources:['atlas-nist','atlas-bipbsn','atlas-salt','atlas-robelin']},
      {id:'gefuege',title:'1 · Phase, Gefüge und Eigenschaft',paragraphs:[
        'Eine Phase ist ein stofflicher Zustand mit bestimmten strukturellen und thermodynamischen Eigenschaften. Ein Gefüge beschreibt zusätzlich die räumliche Anordnung, Form und Größe seiner Bestandteile. Zwei Proben können ähnliche Phasenanteile besitzen und wegen unterschiedlicher Gefügestruktur dennoch verschiedene Eigenschaften zeigen.',
        'Bei Stählen sind Austenit und Ferrit wichtige Phasen. Perlit ist ein Gefügebestandteil aus Ferrit und Zementit. Auch Bainit lässt sich nicht einfach als eine einzelne Gleichgewichtsphase behandeln. Eine farbige Gefügeskizze ist daher eine Orientierung und kein mikroskopisches Bild einer konkreten Probe.',
          'Der Legierungsatlas veranschaulicht vorhandene Phasen durch Körner und Teilchen, lamellare Gemische, Primärkristalle mit Zwischenräumen und mögliche peritektische Reaktionssäume. Primärkristalle und eutektisches Gemisch sind Gefügebestandteile und nicht mit den gesamten Phasenanteilen identisch. In erkennbaren binären und ternären eutektischen Enderstarrungen wird ihre näherungsweise Bilanz aus der letzten Restschmelze abgeleitet. Ein vorausgeschiedener ternärer Anteil kann bereits mehrere Phasen enthalten. Eine Tabelle ordnet die berechnete Folge in Primärerstarrung, gemeinsames Wachstum, Enderstarrung und feste Umwandlungen ein. Qualitative Keimbildung und gerichteter Wärmefluss verändern nur die Skizze. Automatische Reaktionssäume setzen erkannte Vorgänge mit noch vorhandenem Kern und Produkt voraus. Formen, Bildflächen und Größen sind illustrativ. Berechnete Stoffmengen- oder Massenanteile stehen separat daneben; Volumenanteile erfordern Dichten. Keimbildung, Diffusion und Prozessbedingungen fehlen für quantitative Morphologieprognosen.'
      ],equation:'Zusammensetzung + Prozess + räumliche Struktur → Eigenschaften',detail:'Im Legierungsatlas beschreibt ein Gehaltsschnitt verschiedene Gesamtzusammensetzungen. Beim Abkühlen einer Probe bleibt ihr Gesamtgehalt konstant, während sich Zusammensetzung und Anteil der Restschmelze ändern. Für die Interpretation zuerst festlegen, ob ein Diagramm Phasenanteile, Gefügebestandteile oder rein schematische Beispiele zeigt. Diese Begriffe dürfen in Berichten nicht beliebig ausgetauscht werden.',tools:['gefuegerechner','legierungsatlas'],sources:['cambridge','atlas-microstructure','atlas-bargel']},
      {id:'gleichgewicht',title:'2 · Gleichgewicht und endliche Prozesszeit',paragraphs:[
        'Ein Gleichgewichtsdiagramm beschreibt, welche Zustände bei gegebenen Bedingungen thermodynamisch bevorzugt sind. Es sagt nicht automatisch, wie schnell sie entstehen. Reale Wärmebehandlungen dauern endlich lange; Keimbildung, Diffusion und bereits vorhandene Struktur bestimmen den tatsächlich erreichten Zustand.',
        'Beim Erwärmen können sich Phasen auflösen und Austenit bilden. Dafür sind Temperatur, Haltezeit und chemische Zusammensetzung wichtig. Eine einfache sofortige Umwandlungsregel ist eine Modellvereinfachung. Sie darf nicht mit einer vollständigen Beschreibung von Karbidauflösung und Austenitisierung gleichgesetzt werden.'
      ],equation:'Thermodynamik beschreibt den Antrieb; Kinetik beschreibt den Weg und die Geschwindigkeit',detail:'Das Werkzeug trennt Gleichgewichtsskizzen, externe Werkstoffreferenzen und seine eigene Modellrechnung. Herstellerangaben gelten für die dort beschriebenen Bedingungen und werden durch einen Quellenlink nicht automatisch zu numerischen Modellparametern.',tools:['gefuegerechner'],sources:['mit']},
      {id:'ztu',title:'3 · Isotherme und kontinuierliche ZTU-Diagramme',paragraphs:[
        'Isotherme Zeit-Temperatur-Umwandlungsdiagramme betrachten das Halten bei einer Temperatur nach einer geeigneten Vorbehandlung. Kontinuierliche ZTU-Diagramme beschreiben Abkühlverläufe. Weil sich während der Abkühlung die Bedingungen ändern, lassen sich isotherme Startlinien nicht ohne zusätzliches Modell als kontinuierliche Umwandlungskurven benutzen.',
        'Start- und Endkriterien beziehen sich auf definierte Anteile und Versuchsbedingungen. In einem Mehrbestandteil-Modell muss außerdem klar sein, ob ein Anteil relativ zum Gesamtgefüge oder relativ zum erreichbaren Endanteil eines Bestandteils gemeint ist. Die Definition verändert die dargestellten Grenzen.'
      ],equation:'TTT: Halten bei konstanter Temperatur; CCT: Umwandlung entlang eines Abkühlpfads',detail:'Das Werkzeug zeigt für seine Lehrkurven ausdrücklich Modellannahmen. Beim Vergleichen mit Referenzdiagrammen sind Stahlzustand, Austenitisierung und Achseneinheiten zu prüfen. Jede Zeitachse muss dieselbe physikalische Zeit konsistent darstellen.',tools:['gefuegerechner'],sources:['cambridge']},
      {id:'waerme',title:'4 · Wärmeleitung und Rand-Kern-Unterschiede',paragraphs:[
        'Die Oberfläche eines Bauteils tauscht Wärme mit der Umgebung aus. Im Inneren verteilt Wärmeleitung die Energie. Rand und Kern folgen deshalb häufig unterschiedlichen Temperaturpfaden. Die Geometrie und das Verhältnis von Oberfläche zu Volumen beeinflussen diese Unterschiede.',
        'Die Wärmeleitungsgleichung koppelt Temperaturänderung an die räumliche Verteilung des Wärmestroms. Für die Oberfläche wird zusätzlich eine Randbedingung benötigt, zum Beispiel ein vereinfachter konvektiver Wärmeübergang. Konstante Materialwerte und ein konstanter Wärmeübergangskoeffizient sind Näherungen.'
      ],equation:'ρ cp ∂T/∂t = ∇·(k ∇T);   a = k/(ρ cp)',detail:'ρ in kg/m³, cp in J/(kg·K), k in W/(m·K) und Temperaturleitfähigkeit a in m²/s. Die charakteristische thermische Ausgleichszeit wächst etwa mit L²/a. Umwandlungswärme, Strahlung und veränderliche Oberflächenbedingungen können zusätzliche Gleichungen oder Daten erfordern.',tools:['gefuegerechner'],sources:['heat']},
      {id:'stahl-zementit',title:'Übereutektoider Stahl: Zementit an ehemaligen Austenitkorngrenzen',paragraphs:[
        'Bei mehr als 0,76 % C (feste Modellkonvention; oft auf 0,8 % gerundet) kann beim Abkühlen aus Austenit proeutektoider Zementit Fe₃C ausscheiden, bevorzugt an ehemaligen Austenitkorngrenzen. Das ist eine Karbidausscheidung, keine bloße atomare Kohlenstoffanreicherung. Bei 1,00 % C ergeben sich im langsamen Gleichgewichtsgrenzfall etwa 4,1 Massen-% proeutektoider Zementit und 95,9 % Perlit; dessen lamellarer Zementit kommt zusätzlich hinzu. Abschrecken kann diese Ausscheidung unterdrücken.',
        'Die Werkstückrechnung enthält für übereutektoide Fe–C-Modellstähle eine eigene Zementit-Vorreaktion mit Kohlenstoffentzug aus Austenit und zeitabhängige Karbidauflösung beim Erwärmen. Unter Acm können Karbide erhalten bleiben. Die lineare Löslichkeitsnäherung und die JMAK-/Auflösungszeiten sind unkalibrierte Lehrannahmen, keine thermodynamische Bewertung oder Implementierung des Modells von Vogric et al. Die Oberfläche legt alle Parameter offen.',
        'In den ZTU-Lehrdiagrammen ist die Zementit-Vorreaktion separat markiert. Die Skizze zeigt neu aus Austenit ausgeschiedenen Zementit als illustrative Säume, andere überschüssige Karbide als Teilchen. Gezeichnete Grenzlinien sind keine rekonstruierten Austenitkorngrenzen; Belegung, Breite, Zusammenhang und reale Korngröße werden nicht quantitativ vorhergesagt. Die grafische Musterfeinheit beeinflusst die Rechnung nicht. Experimentelle Absicherung und Festigkeitswerte für hohe C-Gehalte fehlen.'
      ],equation:'K_eq = (C₀ − 0,76)/(6,67 − 0,76);   C₀ = A·Cγ + Σ C-Reservoirᵢ',detail:'K_eq ist die Massenfraktion proeutektoiden Zementits im langsamen Grenzfall unterhalb 727 °C. Der restliche Perlit enthält selbst weiteren Zementit. Grenzflächensegregation einzelner C-Atome ist von der Bildung der eigenen Fe₃C-Phase zu unterscheiden. Durchgängige Karbidfilme können die Zähigkeit beeinträchtigen; aus der Skizze folgt keine quantitative Versprödung.',tools:['gefuegerechner'],sources:['steel-cementite','atlas-bargel']},
      {id:'stahl-historie',title:'Zeitabhängige Austenitisierung, Kohlenstoff und Morphologie',paragraphs:[
        'Der Stahlgefügerechner verwendet eine feste Fe–C-Konvention mit 727 °C, 0,76 Massen-% C am Eutektoid, 0,022 % C im Ferrit und 6,67 % C im Zementit. Diese Bezugswerte bleiben beim Ändern des Prozesses konstant. Werkstoffspezifische Ac1/Ac3-Referenzen werden davon getrennt behandelt.',
        'Eine zeitabhängige ZTA-Lehrannahme ersetzt den sofortigen Wechsel zu vollständigem Austenit. Ausgangsmorphologie, Aufheizrate und Haltezeit beeinflussen den angenäherten Anteil, die Homogenisierung und einen dimensionslosen Kornindex. Ohne passende Messdaten entstehen daraus keine experimentellen ZTA-Kurven oder Korngrößen in µm.',
        'Ferritbildung reichert den Rest-Austenit mit Kohlenstoff an. Separate Kohlenstoffreservoirs verfolgen die Bilanz beim Bilden und Auflösen der Bestandteile. Perlit wird als Ferrit und Zementit aufgelöst; Bainit und angelassener Martensit bleiben ohne aufgelöste Karbiddaten mehrphasige Sammelbestände. Grob-/Feinperlit, oberer/unterer Bainit und Einformung sind qualitative Morphologieangaben.',
        'Anlassen wirkt auf vorhandenen Martensit. Später entstehender Martensit erbt keine vorangegangenen heißen Haltezeiten. Ein Härtemoment verfolgt die Beiträge unterschiedlicher Bildungszeiten; Aktivierungsenergien und Härtebeiträge bleiben unkalibrierte Lehrannahmen. Sekundärhärtung und Rest-Austenit-Zerfall werden nicht quantitativ gerechnet.',
        'Konstante Referenzwerte und temperaturabhängige Sensitivitätsprofile für k und cp sind wählbar. Angenommene Öl-/Wasserprofile illustrieren Dampfhaut, Sieden und Konvektion. Optional wirkt eine explizite Umwandlungswärme von ±80 kJ/kg Austenitänderung auf die Temperatur zurück; das ist kein gemessener Enthalpiedatensatz.',
        'Die Gefügeprojektion legt ein ortsfestes synthetisches Voronoi-Muster über das Werkstück. Feste Rangwerte und weich überblendete Zuordnungen illustrieren die lokalen Bestandteile; die Texturflächen sind keine unabhängige Mengenmessung. Die Lupe vergrößert denselben Musterraum, ohne reale Korngröße oder Kornverfolgung zu behaupten. Farbmischung lässt sich vollständig abschalten. Die separat einstellbare Musterfeinheit verändert nur die synthetische Zeichnung und ihre räumliche Abtastung; sie verfeinert weder das thermische Rechengitter noch die zugrunde liegende Umwandlungskinetik. Temperatur, Bestandteile und Morphologie am Messpunkt verwenden dieselbe räumliche Interpolation. Kern, Flächenmitte und Ecke beziehungsweise Kern und Mantel sind gemeinsam vergleichbar.',
        'Feste C45-/42CrMo4-Herstellerbereiche für bestimmte Lieferzustände dienen der Einordnung. HB wird nicht als HV behandelt. Fehlende Chargenanalyse, Ausgangszustand, Austenitisierung, Korngröße und Kühlhistorie sperren die Verwendung als vollständiger Kalibrier- oder unabhängiger Validierungsfall. Jominy ist nicht Bestandteil dieser Erweiterung.'
      ],equation:'C₀ = A·Cγ + Σ C-Reservoirᵢ;   neue Martensitbildung → neue Anlasshistorie',detail:'Methodische Grundlage: Bargel/Siemer, Werkstoffkunde, 14. Auflage (2026). Die Buchdarstellungen liefern keine vollständige numerische Materialdatenbank. Die eigene Prognose und externe Produktreferenzen bleiben getrennt; Anpassung und unabhängige Prüfung dürfen nicht dieselben Daten verwenden.',tools:['gefuegerechner'],sources:['atlas-bargel','cambridge','heat']},
      {id:'grenzen',title:'5 · Martensit, Anlassen und Aussagekraft einer Simulation',paragraphs:[
        'Martensit entsteht beim geeigneten Unterschreiten charakteristischer Temperaturen durch eine Umwandlung mit anderem Mechanismus als rein diffusionsgesteuertes Wachstum. Das anschließende Anlassen verändert den abgeschreckten Zustand erneut. Legierungsabhängige Vorgänge, Ausscheidungen und Rest-Austenit machen die Beschreibung anspruchsvoll.',
        'Härte und Festigkeit lassen sich nicht allgemein aus einer einzigen Farbe oder einem einzigen Phasenanteil bestimmen. Eine quantitative Vorhersage benötigt passende Werkstoffdaten und experimentelle Absicherung. Der Gefügerechner kennzeichnet seine unkalibrierten Anteile und Eigenschaftsabschätzungen als Modellprognosen.',
        'Zur Prüfung gehören bekannte Grenzfälle, Auflösungsabhängigkeit und Vergleiche mit Messungen. Eine feinere Zelle oder mehr Nachkommastellen ersetzen fehlende Materialdaten nicht. Für Referenzwerkstoffe ohne geeignete Kinetik ist eine begrenzte Temperaturrechnung fachlich ehrlicher als erfundene Gefügewerte.'
      ],equation:'Modellprognose + passende Referenzdaten + unabhängige Prüfung → belastbare Einordnung',detail:'Zeitsteuerung und Video zeigen denselben berechneten Verlauf in unterschiedlichen Darstellungsformen. Der Export erweitert die Aussagekraft des zugrunde liegenden Modells nicht.',tools:['gefuegerechner'],sources:['cambridge','mit']}
    ]
  }
};

// Aluminium: freie Lehrkinetik und separate Literaturdaten bewusst trennen.
theory.werkstofftechnik.sources.push({id:'al-age-reference',title:'He et al. (2019) · Auslagern von 6082',url:'https://doi.org/10.3390/met9020173',role:'Originalversuche: Lösungsglühen 545 °C / 50 min, Wasserabschrecken, Auslagern 175 °C. Vier im Text angegebene HV-Werte werden separat dargestellt; keine Kalibrierung der Prozesssimulation.'},{id:'al-hydro',title:'Hydro · Alloy 6082',url:'https://www.hydro.com/globalassets/01-products--services/extruded-profiles/americas/ena-resources/alloy-data-sheets/hydro_2019_data_sheet_6082_revise_1.pdf',role:'Zusammensetzung, Lieferzustände und typische Wärmeleitfähigkeit; keine Ausscheidungskinetik.'});
theory.werkstofftechnik.chapters.push({id:'aluminium-aushaerten',title:'Aluminium: Lösungsglühen, Abschrecken und Auslagern',paragraphs:['Bei aushärtbaren Al-Mg-Si-Legierungen werden lösliche Legierungsbestandteile zunächst in die Aluminiummatrix aufgenommen. Schnelles Abschrecken kann eine übersättigte Lösung erhalten. Während des Auslagerns entstehen Cluster und metastabile Ausscheidungen; ihre Größe, Verteilung und Kohärenz beeinflussen die Behinderung von Versetzungen.','Die freie Simulation für EN AW-6082 beschreibt vier konservativ gekoppelte Reservoirs: gelöst, Cluster/Vorstufen, fein und grob. Diese Prozentwerte beziehen sich auf ein normiertes aushärtungswirksames Legierungsreservoir. Sie sind keine Phasen- oder Volumenanteile des Werkstücks. Die Matrix bleibt erhalten.','Endliche Auflösung, Abschreckverluste, Kaltauslagerung und warme Vergröberung sind unkalibrierte Lehrannahmen. Ein dimensionsloser Aushärtungsindex ersetzt absolute Härte- oder Festigkeitsversprechen. Schematische Körner und Teilchen sind keine berechnete Morphologie oder Größenverteilung.'],equation:'S + C + F + G = 1; Δa = a (1 − exp(−k Δt)); Index = 100 (0,32 S + 0,52 C + F + 0,05 G)',detail:'Jede Zelle koppelt einen impliziten Wärmeleitungsschritt an lokale Reservoirtransfers. Gleichungen und Koeffizienten sind im Tool offengelegt; keine CALPHAD-/KWN-Ausscheidungskinetik, keine Rekristallisation, Schmelze, Spannungen oder Verzug. Kennwerte beschreiben einen gedachten abgekühlten Zustand und keine Warmfestigkeit. Temperaturbereich 0–550 °C. T4/T6 werden nicht allein aus dem Index zugeordnet.',tools:['aluminiumgefuegerechner'],sources:['al-age-reference','al-hydro']},{id:'aluminium-referenz',title:'Aluminium: Literaturkurve und Prozessmodell unterscheiden',paragraphs:['Die separate Referenzansicht zeigt vier im Text einer Originalarbeit genannte Härtewerte bei 175 °C: 83,07, 132,32, 116,87 und 102,23 HV bei 0, 8, 18 und 96 Stunden. Zwischenwerte sind lineare Orientierung, keine zusätzlichen Messungen und kein kinetischer Fit.','Andere Zusammensetzungen, Ausgangszustände, Abschreckwege oder Auslagerungstemperaturen dürfen aus diesen wenigen Punkten nicht quantitativ vorhergesagt werden. Die Quelle liefert keine unabhängige Validierung der freien Reservoirkinetik. Mehrstufige Wärmebehandlungen verlangen zusätzliche Daten und geeignete Modelle.','Der Legierungsatlas bietet passende Gleichgewichtskontexte, unter anderem Al–Mg–Si. Seine Gleichgewichtsanteile bestimmen weder Geschwindigkeit noch metastabile Ausscheidungsfolge oder Festigkeit. Kinetik- und Thermodynamikdaten müssen separat ausgewiesen werden.'],equation:'Referenzpunkt ≠ universelle Materialfunktion; Interpolation ≠ unabhängige Validierung',detail:'Hydro-Stoffwerte und eigene konstante Näherungen dienen der thermischen Lehrrechnung. Die vier Literaturpunkte sind bewusst von den freien Temperaturprogrammen und deren normiertem Index getrennt. Keine Buchabbildungen oder privaten Arbeitsdaten werden öffentlich mitgeliefert.',tools:['aluminiumgefuegerechner','legierungsatlas'],sources:['al-age-reference','al-hydro']});

theory.werkstofftechnik.chapters.push({id:'aluminium-prozessvergleich',title:'Aluminium: Orte und ganze Prozessverläufe vergleichen',paragraphs:['Ein Bauteilquerschnitt beschreibt berechnete Zellmittelwerte. Eine Schnittlinie verbindet Querschnitt, Millimeterprofil, Ablesetext und schematische Ausscheidungslupe am selben Zeitpunkt. Die Linien zwischen Zellmitten sind Darstellungshilfen und ersetzen keine feinere räumliche Berechnung.','Prozessvergleiche können entweder gleiche reale Zeit seit Prozessbeginn oder gleichen relativen Fortschritt t / tEnde gegenüberstellen. Bei verschieden langen Prozessen sind gleiche Fortschrittsanteile unterschiedliche physikalische Zeiten. Jede Kurve endet mit ihrem eigenen berechneten Prozess; nach dem Ende wird keine Fortsetzung erfunden.','Auswerteorte sind Kern, Rand/Ecke, Volumenmittel oder gleiche relative Position. Gleiche relative Position bedeutet bei verschiedenen Abmessungen unterschiedliche Millimeterkoordinaten, beim Rundstab einen Radius. Reservoir-Prozentwerte bleiben auf das Modellreservoir bezogen und sind keine Phasenanteile.'],equation:'Fortschritt = 100 · t / tEnde; Profil: (xZellmitte, Wert); Volumenmittel = Σ(Vi · Wi) / ΣVi',detail:'Gespeicherte Prozesse behalten ihre eigenen Parameter, Gitter und Zeitpunkte. Werte an einer gemeinsamen Zeitmarkierung werden nur innerhalb vorhandener Frames linear interpoliert. Projektdateien speichern validierte Parameter und werden beim Import lokal neu berechnet. Das erweitert die Auswertung des bestehenden Lehrmodells, ohne dessen Kinetik zu kalibrieren.',tools:['aluminiumgefuegerechner'],sources:['al-age-reference','al-hydro']});

{const chapter=theory.werkstofftechnik.chapters.find(c=>c.id==='aluminium-prozessvergleich');chapter.paragraphs.push('Die logarithmische Zeitansicht im Aluminiumrechner verwendet drei äquivalente Achsen in Sekunden, Minuten und Stunden mit Zehnerpotenzen. Kurze und lange Prozessabschnitte sind dadurch gemeinsam ablesbar. Der Zeitpunkt null steht separat, weil sein Logarithmus nicht definiert ist. Relative Prozessvergleiche behalten ihre lineare Prozentachse.');chapter.detail+=' Die positive Logarithmusskala beginnt normalerweise bei 1 s; für Prozesse bis 1 s bei einem Zehntel der Dauer. Die Daten und ihre Interpolation in physikalischer Zeit bleiben unverändert. Die Achsenumrechnung lautet t[s] = 60 t[min] = 3600 t[h].';}
